import webpush from "web-push";

// The one place `web-push` is called (task 5.15-5.16). VAPID keys
// (.env.example) are generated by the human, never by this code (PR
// instructions) — so a deploy without them yet must degrade to "no push
// sent", not a crash, which is why configuration is checked lazily here
// rather than at module load.

export type PushSubscriptionKeys = {
  endpoint: string;
  p256dh: string;
  auth: string;
};

export type PushPayload = {
  title: string;
  body: string;
  /** Where a tap on the notification should open, e.g. "/offers/<id>". */
  url: string;
};

export type SendPushOutcome =
  | { ok: true }
  /** `expired` means the push service itself said this endpoint is gone
   * (404/410) — the caller should delete the subscription (task 5.16). */
  | { ok: false; expired: boolean };

let vapidConfigured = false;

function ensureVapidConfigured(): boolean {
  if (vapidConfigured) {
    return true;
  }
  const { VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY, VAPID_SUBJECT } = process.env;
  if (!VAPID_PUBLIC_KEY || !VAPID_PRIVATE_KEY || !VAPID_SUBJECT) {
    return false;
  }
  webpush.setVapidDetails(VAPID_SUBJECT, VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY);
  vapidConfigured = true;
  return true;
}

function isExpired(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    "statusCode" in error &&
    (error.statusCode === 404 || error.statusCode === 410)
  );
}

/**
 * Sends one push notification. Never throws (task 5.16: "a send failure is
 * logged and doesn't break the action") — a caller only needs to act on
 * `expired`, to delete the subscription.
 */
export async function sendPush(
  subscription: PushSubscriptionKeys,
  payload: PushPayload,
): Promise<SendPushOutcome> {
  if (!ensureVapidConfigured()) {
    console.warn("VAPID keys aren't set — skipping push.");
    return { ok: false, expired: false };
  }

  try {
    await webpush.sendNotification(
      {
        endpoint: subscription.endpoint,
        keys: { p256dh: subscription.p256dh, auth: subscription.auth },
      },
      JSON.stringify(payload),
    );
    return { ok: true };
  } catch (error) {
    console.error("Push send failed:", error);
    return { ok: false, expired: isExpired(error) };
  }
}
